function tcGetElementAnchorPoint(el) {
  try {
    if (!el || !el.getBoundingClientRect) return null;
    const rect = el.getBoundingClientRect();
    if (!rect || rect.width <= 0 || rect.height <= 0) return null;
    // キーボード/ヒント経由の疑似クリックでは mouse 座標が 0,0 になりやすい。
    // Obsidian の Menu はその座標へ出てしまうため、対象ボタンの「下」を基準にする。
    const x = Math.max(8, Math.min(window.innerWidth - 8, rect.left));
    const y = Math.max(8, Math.min(window.innerHeight - 8, rect.bottom + 6));
    return { x, y, rect };
  } catch (e) {
    return null;
  }
}

function tcGetMenuAnchorFromEvent(evt, fallbackEl = null) {
  if (fallbackEl instanceof HTMLElement) return fallbackEl;
  try {
    const hintAnchor = evt && evt.__tcHintAnchorEl;
    if (hintAnchor instanceof HTMLElement) return hintAnchor;
    const current = evt && evt.currentTarget;
    if (current instanceof HTMLElement) return current;
    const target = evt && evt.target;
    if (target instanceof HTMLElement) {
      return target.closest("button, [role='button'], .menu-item, input, select, textarea") || target;
    }
  } catch (e) {}
  return null;
}

function tcEventLooksCoordinateLess(evt) {
  if (!evt) return true;
  // hit-a-hint 経由の疑似クリックは、Obsidian Menu 側で mouse event の座標を
  // 0,0 扱いされることがあるため、常に対象要素の下を基準にメニュー表示する。
  if (evt && evt.__tcFromHint) return true;
  const x = Number(evt.clientX || 0);
  const y = Number(evt.clientY || 0);
  return x === 0 && y === 0;
}

function tcShowMenuAtEventOrAnchor(menu, evt, fallbackEl = null) {
  if (!menu) return;
  const anchor = tcGetMenuAnchorFromEvent(evt, fallbackEl);
  const point = anchor ? tcGetElementAnchorPoint(anchor) : null;
  try {
    if (point && (!evt || tcEventLooksCoordinateLess(evt))) {
      if (typeof menu.showAtPosition === "function") {
        menu.showAtPosition({ x: point.x, y: point.y });
        return;
      }
      if (typeof menu.showAtMouseEvent === "function") {
        const synthetic = new MouseEvent("click", {
          bubbles: true,
          cancelable: true,
          view: window,
          clientX: point.x,
          clientY: point.y,
          screenX: point.x,
          screenY: point.y
        });
        menu.showAtMouseEvent(synthetic);
        return;
      }
    }
    if (evt && typeof menu.showAtMouseEvent === "function") {
      menu.showAtMouseEvent(evt);
      return;
    }
    if (point && typeof menu.showAtPosition === "function") {
      menu.showAtPosition({ x: point.x, y: point.y });
      return;
    }
  } catch (e) {}
  try {
    if (point && typeof menu.showAtPosition === "function") menu.showAtPosition({ x: point.x, y: point.y });
    else if (evt && typeof menu.showAtMouseEvent === "function") menu.showAtMouseEvent(evt);
  } catch (ignored) {}
}

