    const name = cleanProjectValue(key);
    if (!name || !value || typeof value !== "object") return;
    const id = String(value.id || value.project_id || "").trim();
    const archived = value.archived === true || String(value.archived || "").toLowerCase() === "true";
    if (!id && !archived) return;
