        if (!text) {
          new obsidian.Notice("コメントを入力してください");
          try { edit.focus({ preventScroll: true }); } catch (e) { try { edit.focus(); } catch (ignored) {} }
          return;
        }
        const index = findCommentIndex(comment);
        if (index < 0) return restore();
        const next = this.comments.slice();
