    this.settings.bridgePendingFetchLastHttpStatus = Math.max(0, Math.floor(Number(this.settings.bridgePendingFetchLastHttpStatus || 0)));
    this.settings.bridgePendingFetchLastErrorKind = String(this.settings.bridgePendingFetchLastErrorKind || "").trim();
    this.settings.bridgePendingFetchLastResponseOk = !!this.settings.bridgePendingFetchLastResponseOk;
