    this.settings.bridgePendingFetchLastFirstServerSequence = Math.max(0, Math.floor(Number(this.settings.bridgePendingFetchLastFirstServerSequence || 0)));
    this.settings.bridgePendingFetchLastLastServerSequence = Math.max(0, Math.floor(Number(this.settings.bridgePendingFetchLastLastServerSequence || 0)));
    this.settings.bridgeDiagnosticsRetention = this.settings.bridgeDiagnosticsRetention
