    this.settings.bridgeInboundApplyModeAppliedEventIds = Array.from(new Set((Array.isArray(this.settings.bridgeInboundApplyModeAppliedEventIds) ? this.settings.bridgeInboundApplyModeAppliedEventIds : [])
      .map(id => String(id || "").trim()).filter(Boolean))).slice(-100);
    this.settings.bridgeInboundAutoApplyEventTypes = Object.values(this.getBridgeEventRegistry())
