    const after = payload.after && typeof payload.after === "object" && !Array.isArray(payload.after) ? payload.after : {};
    const fromDate = this.normalizeDate(String(from.date || before.date || "").trim());
    const toDate = this.normalizeDate(String(to.date || after.date || payload.date || "").trim());
    const dateChange = !!fromDate && !!toDate && fromDate !== toDate;
    const fromEntryId = String(from.entry_id || before.entry_id || "").trim();
    const toEntryId = String(to.entry_id || after.entry_id || payload.entry_id || "").trim();
