    const bridgeInboundDryRunLastFetchAt = String(this.plugin.settings.bridgeInboundDryRunLastFetchAt || "").trim();
    const bridgeInboundDryRunLastFetchMessage = String(this.plugin.settings.bridgeInboundDryRunLastFetchMessage || "").trim();
    const bridgeInboundDryRunCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundDryRunCount || 0)));
    const bridgeInboundDryRunSelfCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundDryRunSelfCount || 0)));
    const bridgeInboundDryRunRemoteCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundDryRunRemoteCount || 0)));
    const bridgeInboundDryRunEvents = normalizeBridgeInboundDryRunEvents(this.plugin.settings.bridgeInboundDryRunEvents, this.plugin.settings.bridgeDeviceId);
    const bridgeInboundDryRunRawCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundDryRunRawCount || 0)));
    const bridgeInboundDryRunNormalizedCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundDryRunNormalizedCount || bridgeInboundDryRunEvents.length || 0)));
    const bridgeInboundDryRunDisplayCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundDryRunDisplayCount || bridgeInboundDryRunEvents.length || 0)));
    const bridgeInboundDryRunFirstEventType = String(this.plugin.settings.bridgeInboundDryRunFirstEventType || "").trim();
    const bridgeInboundDryRunFirstEventSourceDeviceId = String(this.plugin.settings.bridgeInboundDryRunFirstEventSourceDeviceId || "").trim();
    const bridgeInboundApplyTaskCreatedLastAt = String(this.plugin.settings.bridgeInboundApplyTaskCreatedLastAt || "").trim();
    const bridgeInboundApplyTaskCreatedMessage = String(this.plugin.settings.bridgeInboundApplyTaskCreatedMessage || "").trim();
    const bridgeInboundApplyTaskCreatedAppliedCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundApplyTaskCreatedAppliedCount || 0)));
    const bridgeInboundApplyTaskCreatedSkippedCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundApplyTaskCreatedSkippedCount || 0)));
    const bridgeInboundApplyTaskCreatedFailedCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundApplyTaskCreatedFailedCount || 0)));
    const bridgeInboundApplyTaskCreatedAppliedEventIds = Array.isArray(this.plugin.settings.bridgeInboundApplyTaskCreatedAppliedEventIds)
      ? this.plugin.settings.bridgeInboundApplyTaskCreatedAppliedEventIds.map(id => String(id || "").trim()).filter(Boolean).slice(-10)
      : [];
    const bridgeInboundApplyTaskMovedLastAt = String(this.plugin.settings.bridgeInboundApplyTaskMovedLastAt || "").trim();
    const bridgeInboundApplyTaskMovedMessage = String(this.plugin.settings.bridgeInboundApplyTaskMovedMessage || "").trim();
    const bridgeInboundApplyTaskMovedAppliedCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundApplyTaskMovedAppliedCount || 0)));
    const bridgeInboundApplyTaskMovedSkippedCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundApplyTaskMovedSkippedCount || 0)));
    const bridgeInboundApplyTaskMovedFailedCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundApplyTaskMovedFailedCount || 0)));
    const bridgeInboundApplyTaskMovedAppliedEventIds = Array.isArray(this.plugin.settings.bridgeInboundApplyTaskMovedAppliedEventIds)
      ? this.plugin.settings.bridgeInboundApplyTaskMovedAppliedEventIds.map(id => String(id || "").trim()).filter(Boolean).slice(-10)
      : [];
    const bridgeInboundApplyTaskUpdatedLastAt = String(this.plugin.settings.bridgeInboundApplyTaskUpdatedLastAt || "").trim();
    const bridgeInboundApplyTaskUpdatedMessage = String(this.plugin.settings.bridgeInboundApplyTaskUpdatedMessage || "").trim();
    const bridgeInboundApplyTaskUpdatedAppliedCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundApplyTaskUpdatedAppliedCount || 0)));
    const bridgeInboundApplyTaskUpdatedSkippedCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundApplyTaskUpdatedSkippedCount || 0)));
    const bridgeInboundApplyTaskUpdatedFailedCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeInboundApplyTaskUpdatedFailedCount || 0)));
    const bridgeInboundApplyTaskUpdatedAppliedEventIds = Array.isArray(this.plugin.settings.bridgeInboundApplyTaskUpdatedAppliedEventIds)
      ? this.plugin.settings.bridgeInboundApplyTaskUpdatedAppliedEventIds.map(id => String(id || "").trim()).filter(Boolean).slice(-10)
      : [];
    const bridgeInboundTaskUpdatedProjectDiagnostics = Array.isArray(this.plugin.settings.bridgeInboundTaskUpdatedProjectDiagnostics)
      ? this.plugin.settings.bridgeInboundTaskUpdatedProjectDiagnostics
      : [];
    const latestBridgeInboundTaskUpdatedProjectDiagnostic = bridgeInboundTaskUpdatedProjectDiagnostics[bridgeInboundTaskUpdatedProjectDiagnostics.length - 1] || null;
    const bridgeInboundTaskUpdatedModeDiagnostics = Array.isArray(this.plugin.settings.bridgeInboundTaskUpdatedModeDiagnostics)
      ? this.plugin.settings.bridgeInboundTaskUpdatedModeDiagnostics : [];
    const latestBridgeInboundTaskUpdatedModeDiagnostic = bridgeInboundTaskUpdatedModeDiagnostics[bridgeInboundTaskUpdatedModeDiagnostics.length - 1] || null;
    const bridgeInboundApplyTaskDeletedLastAt = String(this.plugin.settings.bridgeInboundApplyTaskDeletedLastAt || "").trim();
