    const inboundList = el.createDiv({ cls: "tc-bridge-inbound-dry-run-list" });
    inboundList.createEl("div", { text: "受信候補イベント一覧（最大20件）", cls: "tc-setting-subtitle" });
    if (!bridgeInboundDryRunEvents.length) {
      inboundList.createDiv({ text: "表示する受信候補イベントはありません。", cls: "tc-project-settings-empty" });
    } else {
      bridgeInboundDryRunEvents.slice(0, 20).forEach(event => {
        const scope = event.is_self ? "自端末" : "他端末";
        const sourceDeviceId = String(event.source_device_id || event.device_id || "").trim();
        const payload = parseBridgeEventPayload(event);
        const row = inboundList.createDiv({ cls: "tc-bridge-inbound-dry-run-row" });
        row.createDiv({ text: `${event.event_type || "unknown"} / ${scope}`, cls: "tc-bridge-inbound-dry-run-title" });
        row.createDiv({ text: `event_id: ${event.event_id || "-"}`, cls: "tc-diagnostic-meta" });
        row.createDiv({ text: `sourceDeviceId: ${sourceDeviceId || "-"} / task_id: ${event.task_id || "-"} / title: ${event.title || "-"}`, cls: "tc-diagnostic-meta" });
        row.createDiv({ text: `created_at: ${event.created_at ? formatDateTimeForDisplay(event.created_at) : "-"}`, cls: "tc-diagnostic-meta" });
        row.createDiv({ text: `payload概要: ${event.payload_summary || "-"}`, cls: "tc-diagnostic-meta" });
        if (String(event.event_type || "") === "TaskMoved") {
          const valueOrDash = value => {
            if (value === 0) return "0";
            const text = String(value == null ? "" : value).trim();
            return text || "-";
          };
          const from = payload.from && typeof payload.from === "object" && !Array.isArray(payload.from) ? payload.from : {};
          const to = payload.to && typeof payload.to === "object" && !Array.isArray(payload.to) ? payload.to : {};
          const detail = row.createDiv({ cls: "tc-bridge-inbound-task-moved-detail" });
          detail.createDiv({ text: "TaskMoved詳細", cls: "tc-setting-subtitle" });
          detail.createDiv({ text: `event_id: ${valueOrDash(event.event_id)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `event_type: ${valueOrDash(event.event_type)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `sourceDeviceId: ${valueOrDash(sourceDeviceId)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `判定: ${scope}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `task_id: ${valueOrDash(payload.task_id || event.task_id)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `title: ${valueOrDash(payload.title || event.title)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `move_type: ${valueOrDash(payload.move_type)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `from.date: ${valueOrDash(from.date)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `from.section_id: ${valueOrDash(from.section_id || from.section)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `from.section_label: ${valueOrDash(from.section_label)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `from.index: ${valueOrDash(from.index)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `to.date: ${valueOrDash(to.date)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `to.section_id: ${valueOrDash(to.section_id || to.section)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `to.section_label: ${valueOrDash(to.section_label)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `to.index: ${valueOrDash(to.index)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `source_order_task_ids: ${Array.isArray(payload.source_order_task_ids) ? payload.source_order_task_ids.length : "-"}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `target_order_task_ids: ${Array.isArray(payload.target_order_task_ids) ? payload.target_order_task_ids.length : "-"}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `move_payload_version: ${valueOrDash(payload.move_payload_version)}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `taskmoved_payload_source: ${valueOrDash(payload.taskmoved_payload_source)}`, cls: "tc-diagnostic-meta" });
          const orderDiagnostic = payload.order_diagnostic && typeof payload.order_diagnostic === "object" && !Array.isArray(payload.order_diagnostic)
            ? payload.order_diagnostic
            : {};
          detail.createDiv({ text: `before_order: ${Array.isArray(orderDiagnostic.before_order) ? orderDiagnostic.before_order.join(",") : "-"}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `after_move_order: ${Array.isArray(orderDiagnostic.after_move_order) ? orderDiagnostic.after_move_order.join(",") : "-"}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `after_save_order: ${Array.isArray(orderDiagnostic.after_save_order) ? orderDiagnostic.after_save_order.join(",") : "-"}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `after_rebuild_order: ${Array.isArray(orderDiagnostic.after_rebuild_order) ? orderDiagnostic.after_rebuild_order.join(",") : "-"}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `emitted_target_order_task_ids: ${Array.isArray(orderDiagnostic.emitted_target_order_task_ids) ? orderDiagnostic.emitted_target_order_task_ids.join(",") : "-"}`, cls: "tc-diagnostic-meta" });
          detail.createDiv({ text: `created_at: ${valueOrDash(event.created_at ? formatDateTimeForDisplay(event.created_at) : "")}`, cls: "tc-diagnostic-meta" });
        }
      });
    }

    const bridgeOutboxEvents = normalizeBridgeOutboxEvents(this.plugin.settings.bridgeOutboxEvents);
    const bridgeOutboxPendingCount = bridgeOutboxEvents.filter(event => event.status === "pending").length;
    const bridgeOutboxFailedCount = bridgeOutboxEvents.filter(event => event.status === "failed").length;
    const bridgeOutboxStoredSentCount = bridgeOutboxEvents.filter(event => event.status === "sent").length;
    const bridgeOutboxSupersededCount = bridgeOutboxEvents.filter(event => event.status === "superseded").length;
    const bridgeBurstEnqueueCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeOutboxEnqueueCount || 0)));
    const bridgeBurstSentCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeOutboxSentCount || 0)));
    const bridgeBurstDroppedCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeOutboxDroppedCount || 0)));
    const bridgeClockNotSaved = (Array.isArray(this.plugin.settings.bridgeOutboxClockAudit) ? this.plugin.settings.bridgeOutboxClockAudit : [])
      .filter(item => String(item && item.status || "") === "allocated-not-saved");
    const bridgeOutboxMaxBatchSize = normalizeBridgeOutboxLimit(this.plugin.settings.bridgeOutboxMaxBatchSize, 5, 50);
    const bridgeOutboxMaxRetryCount = normalizeBridgeOutboxLimit(this.plugin.settings.bridgeOutboxMaxRetryCount, 5, 100);
    const bridgeOutboxRetryLimitCount = bridgeOutboxEvents.filter(event =>
      event.status === "failed" && Math.max(0, Number(event.retry_count || 0)) >= bridgeOutboxMaxRetryCount
    ).length;
    const bridgeOutboxFlushInProgress = !!this.plugin.settings.bridgeOutboxFlushInProgress;
    const outboxClocks = bridgeOutboxEvents.map(event => Math.max(0, Math.floor(Number(event.logical_clock || 0)))).filter(clock => clock > 0);
    const outboxMinClock = outboxClocks.length ? Math.min(...outboxClocks) : 0;
    const outboxMaxClock = outboxClocks.length ? Math.max(...outboxClocks) : 0;
    const outboxEventTypeCounts = {};
    bridgeOutboxEvents.forEach(event => {
      const type = String(event && event.event_type || "unknown").trim() || "unknown";
      outboxEventTypeCounts[type] = Math.max(0, Number(outboxEventTypeCounts[type] || 0)) + 1;
    });
    const outboxRetryMax = bridgeOutboxEvents.reduce((max, event) => Math.max(max, Math.max(0, Number(event && event.retry_count || 0))), 0);
    const outboxHasLastError = bridgeOutboxEvents.some(event => !!String(event && event.last_error || "").trim());
    const bridgeOutboxDrainMaxBatches = normalizeBridgeOutboxLimit(this.plugin.settings.bridgeOutboxDrainMaxBatches, 10, 100);
    const bridgeOutboxLastDrainBatchCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeOutboxLastDrainBatchCount || 0)));
    const bridgeOutboxLastDrainRemainingCount = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeOutboxLastDrainRemainingCount || 0)));
    const bridgeOutboxD1LatestLogicalClock = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeOutboxD1LatestLogicalClock || 0)));
    const bridgeLogicalClock = Math.max(0, Math.floor(Number(this.plugin.settings.bridgeLogicalClock || 0)));
    const bridgeD1ClockGap = bridgeOutboxD1LatestLogicalClock > 0 ? Math.max(0, bridgeLogicalClock - bridgeOutboxD1LatestLogicalClock) : null;
    const bridgeOutboxTaskMovedCount = Math.max(0, Number(outboxEventTypeCounts.TaskMoved || 0));
    const bridgeOutboxActiveCount = bridgeOutboxPendingCount + bridgeOutboxFailedCount + bridgeOutboxStoredSentCount;
    const bridgeOutboxActiveTaskMovedCount = bridgeOutboxEvents.filter(event =>
      event.event_type === "TaskMoved" && ["pending", "failed", "sent"].includes(event.status)
    ).length;
    const bridgeTaskMovedCoalesceCount = Math.max(0, Number(this.plugin.settings.bridgeTaskMovedCoalesceCount || 0));
    const bridgeTaskMovedSupersededTotalCount = Math.max(0, Number(this.plugin.settings.bridgeTaskMovedSupersededCount || 0));
    const bridgeTaskMovedLastFinalPayloadSummary = String(this.plugin.settings.bridgeTaskMovedLastFinalPayloadSummary || "").trim();
    const bridgeTaskCreatedRenameMergeCount = Math.max(0, Number(this.plugin.settings.bridgeTaskCreatedRenameMergeCount || 0));
    const bridgeTaskCreatedLastRenameMergeTaskId = String(this.plugin.settings.bridgeTaskCreatedLastRenameMergeTaskId || "").trim();
    const bridgeTaskCreatedLastRenameMergeEntryId = String(this.plugin.settings.bridgeTaskCreatedLastRenameMergeEntryId || "").trim();
    const bridgeTaskCreatedLastFinalTitleSummary = String(this.plugin.settings.bridgeTaskCreatedLastFinalTitleSummary || "").trim();
    const bridgeTaskCreatedRenameHandoffDiagnostics = Array.isArray(this.plugin.settings.bridgeTaskCreatedRenameHandoffDiagnostics)
      ? this.plugin.settings.bridgeTaskCreatedRenameHandoffDiagnostics : [];
    const latestBridgeTaskCreatedRenameHandoffDiagnostic = bridgeTaskCreatedRenameHandoffDiagnostics[bridgeTaskCreatedRenameHandoffDiagnostics.length - 1] || null;
    const bridgeTaskCreatedTimeMergeCount = Math.max(0, Number(this.plugin.settings.bridgeTaskCreatedTimeMergeCount || 0));
    const bridgeTaskCreatedLastTimeMergeTaskId = String(this.plugin.settings.bridgeTaskCreatedLastTimeMergeTaskId || "").trim();
    const bridgeTaskCreatedLastTimeMergeEntryId = String(this.plugin.settings.bridgeTaskCreatedLastTimeMergeEntryId || "").trim();
    const bridgeTaskCreatedLastTimeMergeChangedFields = Array.isArray(this.plugin.settings.bridgeTaskCreatedLastTimeMergeChangedFields) ? this.plugin.settings.bridgeTaskCreatedLastTimeMergeChangedFields : [];
    const bridgeTaskCreatedLastFinalTimeSummary = String(this.plugin.settings.bridgeTaskCreatedLastFinalTimeSummary || "").trim();
    const bridgeProjectSyncEnqueueCount = Math.max(0, Number(this.plugin.settings.bridgeProjectSyncEnqueueCount || 0));
    const bridgeProjectSyncApplyCount = Math.max(0, Number(this.plugin.settings.bridgeProjectSyncApplyCount || 0));
    const bridgeProjectSyncLastProjectId = String(this.plugin.settings.bridgeProjectSyncLastProjectId || "").trim();
    const bridgeProjectSyncLastProjectName = String(this.plugin.settings.bridgeProjectSyncLastProjectName || "").trim();
    const bridgeProjectSyncLastEventType = String(this.plugin.settings.bridgeProjectSyncLastEventType || "").trim();
    const bridgeProjectSyncLastResult = String(this.plugin.settings.bridgeProjectSyncLastResult || "").trim();
    const bridgeModeSyncEnqueueCount = Math.max(0, Number(this.plugin.settings.bridgeModeSyncEnqueueCount || 0));
    const bridgeModeSyncApplyCount = Math.max(0, Number(this.plugin.settings.bridgeModeSyncApplyCount || 0));
    const bridgeModeSyncLastModeId = String(this.plugin.settings.bridgeModeSyncLastModeId || "").trim();
    const bridgeModeSyncLastModeName = String(this.plugin.settings.bridgeModeSyncLastModeName || "").trim();
    const bridgeModeSyncLastEventType = String(this.plugin.settings.bridgeModeSyncLastEventType || "").trim();
    const bridgeModeSyncLastResult = String(this.plugin.settings.bridgeModeSyncLastResult || "").trim();
    const bridgeAttributeSyncEnqueueCount = Math.max(0, Number(this.plugin.settings.bridgeAttributeSyncEnqueueCount || 0));
    const bridgeAttributeSyncApplyCount = Math.max(0, Number(this.plugin.settings.bridgeAttributeSyncApplyCount || 0));
    const bridgeSectionSyncEnqueueCount = Math.max(0, Number(this.plugin.settings.bridgeSectionSyncEnqueueCount || 0));
    const bridgeSectionSyncApplyCount = Math.max(0, Number(this.plugin.settings.bridgeSectionSyncApplyCount || 0));
    const bridgeOutboxMinimalMoveTestWarning = bridgeOutboxActiveCount > 0
      ? `警告: 送信対象outboxに${bridgeOutboxActiveCount}件（TaskMoved ${bridgeOutboxActiveTaskMovedCount}件）が残っています。TaskMovedの最小検証前に送信対象を空にしてください。`
      : `送信対象outboxは空です。TaskMovedの最小検証を開始できます（superseded履歴 ${bridgeOutboxSupersededCount}件）。`;

    el.createEl("h4", { text: "Bridge送信診断" });

    new obsidian.Setting(el)
      .setName("Bridge / 自動送信（Auto flush local changes）")
      .setDesc(`bridgeEnabled ${this.plugin.settings.bridgeEnabled ? "true" : "false"} / bridgeAutoFlushEnabled ${this.plugin.settings.bridgeAutoFlushEnabled ? "true" : "false"}`);

    new obsidian.Setting(el)
      .setName("logical clock / batch")
      .setDesc(`local ${bridgeLogicalClock} / max batch size ${bridgeOutboxMaxBatchSize} / drain max batches ${bridgeOutboxDrainMaxBatches}`);

    new obsidian.Setting(el)
      .setName("outbox logical_clock範囲")
      .setDesc(outboxClocks.length ? `${outboxMinClock}〜${outboxMaxClock} / ${bridgeOutboxEvents.length}件` : "outboxなし");

    new obsidian.Setting(el)
      .setName("outbox event_type別件数")
      .setDesc(Object.keys(outboxEventTypeCounts).length
        ? Object.entries(outboxEventTypeCounts).map(([type, count]) => `${type}:${count}`).join(" / ")
        : "outboxなし");

    new obsidian.Setting(el)
      .setName("retry / last_error")
      .setDesc(`retry_count最大 ${outboxRetryMax} / last_error ${outboxHasLastError ? "あり" : "なし"}`);

    new obsidian.Setting(el)
      .setName("最終drain")
      .setDesc(`batch ${bridgeOutboxLastDrainBatchCount} / 残件 ${bridgeOutboxLastDrainRemainingCount}`);

    new obsidian.Setting(el)
      .setName("D1上の自device最新 logical_clock")
      .setDesc(bridgeOutboxD1LatestLogicalClock > 0
        ? `${bridgeOutboxD1LatestLogicalClock} / localとの差分 ${bridgeD1ClockGap}`
        : "API応答から未取得");

    new obsidian.Setting(el)
      .setName("token/API URL/payload抜き送信診断JSONをコピー")
      .setDesc("許可した送信状態だけをコピーします。API token、API URL、payload、data.json全文は含みません。")
      .addButton(btn => btn
        .setButtonText("コピー")
        .onClick(async () => {
          btn.setDisabled(true);
          try {
            const text = JSON.stringify({
              diagnostic_type: "taskchute_bridge_outbound",
              copied_at: nowIso(),
              bridge_enabled: !!this.plugin.settings.bridgeEnabled,
              bridge_auto_flush_enabled: !!this.plugin.settings.bridgeAutoFlushEnabled,
              bridge_auto_flush_run_active: !!this.plugin.bridgeAutoFlushRunActive,
              bridge_auto_flush_reschedule_pending: !!this.plugin.bridgeAutoFlushRescheduleRequested,
              bridge_auto_flush_reschedule_requested_count: Math.max(0, Number(this.plugin.settings.bridgeAutoFlushRescheduleRequestedCount || 0)),
              bridge_auto_flush_reschedule_executed_count: Math.max(0, Number(this.plugin.settings.bridgeAutoFlushRescheduleExecutedCount || 0)),
              bridge_auto_flush_reschedule_not_needed_count: Math.max(0, Number(this.plugin.settings.bridgeAutoFlushRescheduleNotNeededCount || 0)),
              bridge_auto_flush_last_reschedule_requested_at: String(this.plugin.settings.bridgeAutoFlushLastRescheduleRequestedAt || "").trim() || null,
              bridge_auto_flush_last_reschedule_executed_at: String(this.plugin.settings.bridgeAutoFlushLastRescheduleExecutedAt || "").trim() || null,
              bridge_auto_flush_last_reschedule_not_needed_at: String(this.plugin.settings.bridgeAutoFlushLastRescheduleNotNeededAt || "").trim() || null,
              bridge_auto_flush_last_reschedule_reason: String(this.plugin.settings.bridgeAutoFlushLastRescheduleReason || "").trim() || null,
              bridge_auto_flush_last_reschedule_decision: String(this.plugin.settings.bridgeAutoFlushLastRescheduleDecision || "").trim() || null,
              bridge_logical_clock: bridgeLogicalClock,
              bridge_outbox_max_batch_size: bridgeOutboxMaxBatchSize,
              bridge_outbox_drain_max_batches: bridgeOutboxDrainMaxBatches,
              outbox_count: bridgeOutboxEvents.length,
              outbox_min_logical_clock: outboxMinClock || null,
              outbox_max_logical_clock: outboxMaxClock || null,
              event_type_counts: outboxEventTypeCounts,
              taskmoved_outbox_count: bridgeOutboxTaskMovedCount,
              taskmoved_active_outbox_count: bridgeOutboxActiveTaskMovedCount,
              taskmoved_superseded_stored_count: bridgeOutboxSupersededCount,
              taskmoved_coalesce_count: bridgeTaskMovedCoalesceCount,
              taskmoved_superseded_total_count: bridgeTaskMovedSupersededTotalCount,
              taskmoved_last_final_payload_summary: bridgeTaskMovedLastFinalPayloadSummary,
              taskcreated_rename_merge_count: bridgeTaskCreatedRenameMergeCount,
              taskcreated_last_rename_merge_task_id: bridgeTaskCreatedLastRenameMergeTaskId || null,
              taskcreated_last_rename_merge_entry_id: bridgeTaskCreatedLastRenameMergeEntryId || null,
              taskcreated_last_final_title_summary: bridgeTaskCreatedLastFinalTitleSummary || null,
              taskcreated_rename_handoff_latest: latestBridgeTaskCreatedRenameHandoffDiagnostic,
              taskcreated_time_merge_count: bridgeTaskCreatedTimeMergeCount,
              taskcreated_last_time_merge_task_id: bridgeTaskCreatedLastTimeMergeTaskId || null,
              taskcreated_last_time_merge_entry_id: bridgeTaskCreatedLastTimeMergeEntryId || null,
              taskcreated_last_time_merge_changed_fields: bridgeTaskCreatedLastTimeMergeChangedFields,
              taskcreated_last_final_time_summary: bridgeTaskCreatedLastFinalTimeSummary || null,
              project_sync_enqueue_count: bridgeProjectSyncEnqueueCount,
              project_sync_apply_count: bridgeProjectSyncApplyCount,
              project_sync_last_project_id: bridgeProjectSyncLastProjectId || null,
              project_sync_last_project_name: bridgeProjectSyncLastProjectName || null,
              project_sync_last_event_type: bridgeProjectSyncLastEventType || null,
              project_sync_last_result: bridgeProjectSyncLastResult || null,
              mode_sync_enqueue_count: bridgeModeSyncEnqueueCount,
              mode_sync_apply_count: bridgeModeSyncApplyCount,
              mode_sync_last_mode_id: bridgeModeSyncLastModeId || null,
              mode_sync_last_mode_name: bridgeModeSyncLastModeName || null,
              mode_sync_last_event_type: bridgeModeSyncLastEventType || null,
              mode_sync_last_result: bridgeModeSyncLastResult || null,
              attribute_sync_enqueue_count: bridgeAttributeSyncEnqueueCount,
              attribute_sync_apply_count: bridgeAttributeSyncApplyCount,
              attribute_sync_last_kind: String(this.plugin.settings.bridgeAttributeSyncLastKind || "").trim() || null,
              attribute_sync_last_id: String(this.plugin.settings.bridgeAttributeSyncLastId || "").trim() || null,
              attribute_sync_last_name: String(this.plugin.settings.bridgeAttributeSyncLastName || "").trim() || null,
              section_sync_enqueue_count: bridgeSectionSyncEnqueueCount,
              section_sync_apply_count: bridgeSectionSyncApplyCount,
              section_sync_last_section_id: String(this.plugin.settings.bridgeSectionSyncLastSectionId || "").trim() || null,
              taskmoved_minimal_test_blocked: bridgeOutboxActiveCount > 0,
              retry_count_max: outboxRetryMax,
              has_last_error: outboxHasLastError,
              last_flush_at: String(this.plugin.settings.bridgeOutboxLastFlushAt || "").trim(),
              last_flush_ok: !!this.plugin.settings.bridgeOutboxLastFlushOk,
              last_flush_message: String(this.plugin.settings.bridgeOutboxLastFlushMessage || "").trim(),
              last_flush_sent_count: Math.max(0, Number(this.plugin.settings.bridgeOutboxLastFlushSentCount || 0)),
              last_flush_failed_count: Math.max(0, Number(this.plugin.settings.bridgeOutboxLastFlushFailedCount || 0)),
              last_flush_skipped_reason: String(this.plugin.settings.bridgeOutboxLastFlushSkippedReason || "").trim(),
              enqueue_count: bridgeBurstEnqueueCount,
              sent_count: bridgeBurstSentCount,
              dropped_count: bridgeBurstDroppedCount,
              d1_device_latest_logical_clock: bridgeOutboxD1LatestLogicalClock || null,
              local_d1_clock_gap: bridgeD1ClockGap
            }, null, 2);
            if (!navigator.clipboard || typeof navigator.clipboard.writeText !== "function") throw new Error("clipboard unavailable");
            await navigator.clipboard.writeText(text);
            new obsidian.Notice("token/API URL/payload抜きBridge送信診断情報をコピーしました。");
          } catch (e) {
            new obsidian.Notice("Bridge送信診断情報をコピーできませんでした。");
          } finally {
            btn.setDisabled(false);
          }
        }));

    new obsidian.Setting(el)
      .setName("outbox状態")
      .setDesc(`総件数 ${bridgeOutboxEvents.length}件 / pending ${bridgeOutboxPendingCount}件 / failed ${bridgeOutboxFailedCount}件 / superseded ${bridgeOutboxSupersededCount}件 / sent残存 ${bridgeOutboxStoredSentCount}件 / retry上限到達 ${bridgeOutboxRetryLimitCount}件 / 送信中 ${bridgeOutboxFlushInProgress ? "はい" : "いいえ"}`);

    new obsidian.Setting(el)
      .setName("TaskMoved最小検証")
      .setDesc(bridgeOutboxMinimalMoveTestWarning);

    new obsidian.Setting(el)
      .setName("outboxバースト診断")
      .setDesc(`enqueue_count ${bridgeBurstEnqueueCount} / outbox_count ${bridgeOutboxEvents.length} / sent_count ${bridgeBurstSentCount} / remaining_count ${bridgeOutboxPendingCount + bridgeOutboxFailedCount} / dropped_count ${bridgeBurstDroppedCount}`);

    new obsidian.Setting(el)
      .setName("TaskMoved coalesce診断")
      .setDesc(`coalesce ${bridgeTaskMovedCoalesceCount}回 / superseded累計 ${bridgeTaskMovedSupersededTotalCount}件 / superseded保存中 ${bridgeOutboxSupersededCount}件`);

    new obsidian.Setting(el)
      .setName("TaskMoved最終送信payload概要")
      .setDesc(bridgeTaskMovedLastFinalPayloadSummary || "未記録");

    new obsidian.Setting(el)
      .setName("TaskCreated rename merge診断")
      .setDesc(`pending TaskCreatedへのmerge ${bridgeTaskCreatedRenameMergeCount}件 / task_id ${bridgeTaskCreatedLastRenameMergeTaskId || "-"} / entry_id ${bridgeTaskCreatedLastRenameMergeEntryId || "-"} / 最終title ${bridgeTaskCreatedLastFinalTitleSummary || "-"}`);

    new obsidian.Setting(el)
      .setName("TaskCreated rename handoff診断")
      .setDesc(latestBridgeTaskCreatedRenameHandoffDiagnostic
        ? `${latestBridgeTaskCreatedRenameHandoffDiagnostic.recorded_at || "-"} / ${latestBridgeTaskCreatedRenameHandoffDiagnostic.phase || "-"} / task_id ${latestBridgeTaskCreatedRenameHandoffDiagnostic.task_id || "-"} / entry_id ${latestBridgeTaskCreatedRenameHandoffDiagnostic.entry_id || "-"} / decision ${latestBridgeTaskCreatedRenameHandoffDiagnostic.decision || "-"}`
        : "診断履歴なし");

    new obsidian.Setting(el)
      .setName("Bridge時間フィールドmerge診断")
      .setDesc(`pending TaskCreated/送信前補正 ${bridgeTaskCreatedTimeMergeCount}件 / task_id ${bridgeTaskCreatedLastTimeMergeTaskId || "-"} / entry_id ${bridgeTaskCreatedLastTimeMergeEntryId || "-"} / changed_fields ${bridgeTaskCreatedLastTimeMergeChangedFields.join(", ") || "-"} / ${bridgeTaskCreatedLastFinalTimeSummary || "未記録"}`);

    new obsidian.Setting(el)
      .setName("Bridge Project同期診断")
      .setDesc(`enqueue ${bridgeProjectSyncEnqueueCount}件 / apply ${bridgeProjectSyncApplyCount}件 / ${bridgeProjectSyncLastEventType || "-"} / project_id ${bridgeProjectSyncLastProjectId || "-"} / project_name ${bridgeProjectSyncLastProjectName || "-"} / 結果 ${bridgeProjectSyncLastResult || "-"}`);

    new obsidian.Setting(el)
      .setName("Bridge Mode同期診断")
      .setDesc(`enqueue ${bridgeModeSyncEnqueueCount}件 / apply ${bridgeModeSyncApplyCount}件 / ${bridgeModeSyncLastEventType || "-"} / mode_id ${bridgeModeSyncLastModeId || "-"} / mode_name ${bridgeModeSyncLastModeName || "-"} / 結果 ${bridgeModeSyncLastResult || "-"}`);

    new obsidian.Setting(el)
      .setName("Bridge Category / Area / Client同期診断")
      .setDesc(`enqueue ${bridgeAttributeSyncEnqueueCount}件 / apply ${bridgeAttributeSyncApplyCount}件 / ${this.plugin.settings.bridgeAttributeSyncLastKind || "-"} / id ${this.plugin.settings.bridgeAttributeSyncLastId || "-"} / name ${this.plugin.settings.bridgeAttributeSyncLastName || "-"} / 結果 ${this.plugin.settings.bridgeAttributeSyncLastResult || "-"}`);

    new obsidian.Setting(el)
      .setName("Bridge Section同期診断")
      .setDesc(`enqueue ${bridgeSectionSyncEnqueueCount}件 / apply ${bridgeSectionSyncApplyCount}件 / ${this.plugin.settings.bridgeSectionSyncLastEventType || "-"} / section_id ${this.plugin.settings.bridgeSectionSyncLastSectionId || "-"} / 結果 ${this.plugin.settings.bridgeSectionSyncLastResult || "-"}`);

    new obsidian.Setting(el)
      .setName("採番後outbox未保存")
      .setDesc(bridgeClockNotSaved.length
        ? bridgeClockNotSaved.slice(-10).map(item => `${item.logical_clock}:${item.event_type || "unknown"}:${item.event_id}`).join(" / ")
        : "検出なし");

    const taskCreatedOrderDiagnostics = Array.isArray(this.plugin.settings.taskCreatedOrderDiagnostics)
      ? this.plugin.settings.taskCreatedOrderDiagnostics
      : [];
    const latestTaskCreatedOrderDiagnostic = taskCreatedOrderDiagnostics[taskCreatedOrderDiagnostics.length - 1] || null;
    new obsidian.Setting(el)
      .setName("TaskCreatedセクション順序診断")
      .setDesc(latestTaskCreatedOrderDiagnostic
        ? `直近 ${latestTaskCreatedOrderDiagnostic.recorded_at || "-"} / ${latestTaskCreatedOrderDiagnostic.operation || "-"} / 保存前後 ${latestTaskCreatedOrderDiagnostic.ok ? "正常" : `変更検出: ${(latestTaskCreatedOrderDiagnostic.changed_sections || []).join(", ")}`} / 描画前後 ${latestTaskCreatedOrderDiagnostic.render_ok == null ? "未確認" : latestTaskCreatedOrderDiagnostic.render_ok ? "正常" : `変更検出: ${(latestTaskCreatedOrderDiagnostic.render_changed_sections || []).join(", ")}`}`
        : "診断履歴なし");

    const taskMovedOrderDiagnostics = Array.isArray(this.plugin.settings.taskMovedOrderDiagnostics)
      ? this.plugin.settings.taskMovedOrderDiagnostics
      : [];
    const latestTaskMovedOrderDiagnostic = taskMovedOrderDiagnostics[taskMovedOrderDiagnostics.length - 1] || null;
    new obsidian.Setting(el)
      .setName("TaskMovedセクション順序診断")
      .setDesc(latestTaskMovedOrderDiagnostic
        ? `section_id ${latestTaskMovedOrderDiagnostic.section_id || "-"} / before ${JSON.stringify(latestTaskMovedOrderDiagnostic.before_order || [])} / after_move ${JSON.stringify(latestTaskMovedOrderDiagnostic.after_move_order || [])} / after_save ${JSON.stringify(latestTaskMovedOrderDiagnostic.after_save_order || [])} / after_rebuild ${JSON.stringify(latestTaskMovedOrderDiagnostic.after_rebuild_order || [])} / emitted ${JSON.stringify(latestTaskMovedOrderDiagnostic.emitted_target_order_task_ids || [])}`
        : "診断履歴なし");

    const taskDragMoveDiagnostics = Array.isArray(this.plugin.settings.bridgeTaskDragMoveDiagnostics)
      ? this.plugin.settings.bridgeTaskDragMoveDiagnostics
      : [];
    const latestTaskDragMoveDiagnostic = taskDragMoveDiagnostics[taskDragMoveDiagnostics.length - 1] || null;
    new obsidian.Setting(el)
      .setName("Task D&D Bridge診断")
      .setDesc(latestTaskDragMoveDiagnostic
        ? `${latestTaskDragMoveDiagnostic.recorded_at || "-"} / ${latestTaskDragMoveDiagnostic.phase || "-"} / entry_id ${latestTaskDragMoveDiagnostic.entry_id || "-"} / before ${JSON.stringify(latestTaskDragMoveDiagnostic.before_order_entry_ids || [])} / after ${JSON.stringify(latestTaskDragMoveDiagnostic.after_order_entry_ids || [])} / enqueue ${latestTaskDragMoveDiagnostic.enqueue_attempted ? latestTaskDragMoveDiagnostic.enqueue_result ? "成功" : "失敗" : `skip: ${latestTaskDragMoveDiagnostic.enqueue_skipped_reason || "-"}`}`
        : "診断履歴なし");

    const taskMovedSectionDiagnostics = Array.isArray(this.plugin.settings.taskMovedSectionDiagnostics)
      ? this.plugin.settings.taskMovedSectionDiagnostics
      : [];
    const latestTaskMovedSectionDiagnostic = taskMovedSectionDiagnostics[taskMovedSectionDiagnostics.length - 1] || null;
    new obsidian.Setting(el)
